templates.home:
{{template "top" .}}<div class="hero"><h1>{{.agencyName}}</h1>{{with .tagline}}<p class="muted">{{.}}</p>{{end}}{{template "searchform" .}}</div>
<h2>{{.t.featured}}</h2>{{if .featured}}<div class="grid">{{range .featured}}{{template "card" .}}{{end}}</div>{{else}}<p class="muted">{{.t.no_results}}</p>{{end}}
<p><a class="btn secondary" href="/search{{if eq .lang "ar"}}?lang=ar{{end}}">{{.t.view_all}}</a></p>
{{if .agents}}<h2>{{.t.our_agents}}</h2><div class="grid">{{range .agents}}<a class="card" href="{{.url}}"><div class="body person"><div class="avatar">{{if .photo}}<img src="{{.photo}}?w=160" alt="{{.name}}" loading="lazy">{{else}}{{.initial}}{{end}}</div>
<div><div><strong>{{.name}}</strong></div>{{with .brn}}<div class="muted">{{$.t.brn}} {{.}}</div>{{end}}{{with .languages}}<div class="muted">{{.}}</div>{{end}}</div></div></a>{{end}}</div>{{end}}
{{with .about}}<h2>{{$.t.about}}</h2><p class="pre">{{.}}</p>{{end}}
<div class="panel"><h2>{{.t.list_property}}</h2><p class="muted">{{.t.list_property_intro}}</p><a class="btn" href="/list-your-property{{if eq .lang "ar"}}?lang=ar{{end}}">{{.t.request_valuation}}</a></div>
{{template "bottom" .}}

templates.search:
{{template "top" .}}<h1>{{.title}}</h1><div class="panel">{{template "searchform" .}}</div>
<p class="muted">{{.total}} {{.t.results}}</p><div class="chips">{{range .sorts}}<a class="chip{{if .on}} on{{end}}" href="{{.url}}">{{.label}}</a>{{end}}</div>
{{if .listings}}<div class="grid">{{range .listings}}{{template "card" .}}{{end}}</div>
<div class="pager">{{if .prev}}<a class="btn secondary" rel="prev" href="{{.prev}}">{{.t.previous}}</a>{{end}}<span class="muted">{{.t.page}} {{.pageNo}} / {{.pages}}</span>{{if .next}}<a class="btn secondary" rel="next" href="{{.next}}">{{.t.next}}</a>{{end}}</div>
