scripts.home:
const TYPES = ['apartment', 'villa', 'townhouse', 'penthouse', 'office', 'shop', 'land'];
const HOMES = ['apartment', 'villa', 'townhouse', 'penthouse'];
const KINDS = ['enquiry', 'viewing', 'callback', 'valuation'];
function langOf(req) {
  const l = (req.query && req.query.lang) || (req.form && req.form.lang) || (req.body && req.body.lang);
  return l === 'ar' ? 'ar' : 'en';
}
function texts(lang) {
  const t = {};
  for (const r of db.query('SELECT key, en, ar FROM texts')) t[r.key] = (lang === 'ar' ? r.ar : r.en) || r.en;
  return t;
}
function agency() { return db.query('SELECT * FROM agency ORDER BY id LIMIT 1')[0]; }
function digits(s) { return String(s || '').replace(/[^0-9]/g, ''); }
// 1850000 -> "1,850,000"
function aed(n) {
  const s = String(Math.round(Number(n) || 0));
  let out = '';
  for (let i = 0; i < s.length; i++) out += (i > 0 && (s.length - i) % 3 === 0 ? ',' : '') + s[i];
  return out;
}
function pick(row, col, lang) { return lang === 'ar' && row[col + '_ar'] ? row[col + '_ar'] : row[col]; }
// UTC "YYYY-MM-DD HH:MM:SS", as in created_at, shifted by ms.
function utc(ms) { return new Date(Date.now() + (ms || 0)).toISOString().replace('T', ' ').slice(0, 19); }
// Today's date in Dubai (UTC+4), "YYYY-MM-DD".
function dubaiToday() { return new Date(Date.now() + 4 * 3600 * 1000).toISOString().slice(0, 10); }
// The rule for what visitors may see: available or reserved, and with a permit number
// unless the owner turned "hide without permit" off. Constant SQL, no visitor data.
function publicWhere(a) {
  return "status IN ('available', 'reserved')" + (a.hide_without_permit === 0 ? '' : " AND trim(coalesce(permit_number, '')) != ''");
}
function page(req, extra) {
  const lang = langOf(req), a = agency(), t = texts(lang);
  const base = {lang: lang, dir: lang === 'ar' ? 'rtl' : 'ltr', other: lang === 'ar' ? 'en' : 'ar', t: t, a: a,
    agencyName: pick(a, 'name', lang), tagline: pick(a, 'tagline', lang), path: req.path,
    wa: digits(a.whatsapp), title: '', minDate: dubaiToday()};
  const e = req.query && req.query.error;
  if (e && /^error_[a-z_]+$/.test(e) && t[e]) base.error = t[e];
  for (const k in extra) base[k] = extra[k];
  return base;
}
// A listing as shown on cards and returned by the tools, with every label in the visitor's language.
function card(l, lang, t) {
  const home = HOMES.indexOf(l.property_type) >= 0 && l.bedrooms !== null;
  const beds = !home ? '' : l.bedrooms === 0 ? t.studio : l.bedrooms + ' ' + (l.bedrooms === 1 ? t.bed : t.beds);
  const baths = l.bathrooms ? l.bathrooms + ' ' + (l.bathrooms === 1 ? t.bath : t.baths) : '';
  const area = l.area_sqft ? aed(l.area_sqft) + ' ' + t.sqft : '';
  const images = [];
  for (let i = 1; i <= 6; i++) if (l['image' + i]) images.push(l['image' + i]);
  return {id: l.id, ref: l.reference || ('#' + l.id), refLabel: t.ref, title: pick(l, 'title', lang), purpose: l.purpose,
    purposeLabel: l.purpose === 'rent' ? t.for_rent : t.for_sale, type: l.property_type, typeLabel: t['type_' + l.property_type] || l.property_type,
    price: aed(l.price), priceNum: l.price, period: l.purpose !== 'rent' ? '' : l.rent_period === 'monthly' ? t.per_month : t.per_year,
    beds: beds, baths: baths, area: area, summary: [beds, baths, area].filter(Boolean).join(' · '),
    place: [l.building, l.community, l.emirate].filter(Boolean).join(', '), community: l.community,
    offplanLabel: l.offplan ? t.offplan : '', reservedLabel: l.status === 'reserved' ? t.reserved : '',
    image: images.length ? images[0] : '', images: images, permit: (l.permit_number || '').trim(),
    url: '/l/' + l.id + (lang === 'ar' ? '?lang=ar' : '')};
}
function agentCard(x, lang) {
  const name = pick(x, 'name', lang) || '';
  return {id: x.id, name: name, initial: Array.from(name)[0] || '', photo: x.photo, phone: x.phone, phoneDigits: digits(x.phone), wa: digits(x.whatsapp),
    email: x.email, brn: x.brn, languages: x.languages, bio: pick(x, 'bio', lang), url: '/agents/' + x.id + (lang === 'ar' ? '?lang=ar' : '')};
}
// [{value, label, on}] for a <select> or a radio group.
function opts(values, label, current) { return values.map(v => ({value: v, label: label(v), on: String(v) === String(current)})); }
// Everything the search form needs; f is the current filter {purpose, type, community, beds, min, max}.
function searchForm(a, t, f) {
  const communities = db.query('SELECT DISTINCT community FROM listings WHERE ' + publicWhere(a) + " AND coalesce(community, '') != '' ORDER BY community").map(r => r.community);
  return {purposes: opts(['sale', 'rent'], v => v === 'rent' ? t.rent : t.buy, f.purpose), types: opts(TYPES, v => t['type_' + v] || v, f.type),
    communities: opts(communities, v => v, f.community),
    bedsOptions: opts([0, 1, 2, 3, 4], v => v === 0 ? t.studio : v === 4 ? '4+' : String(v), f.beds < 0 ? '' : f.beds),
    min: f.min > 0 ? String(f.min) : '', max: f.max > 0 ? String(f.max) : ''};
}
// The kinds a lead form offers, the chosen one first selected.
function leadKinds(t, kinds, chosen) { return opts(kinds, v => t['kind_' + v], kinds.indexOf(chosen) >= 0 ? chosen : kinds[0]); }

// GET /?lang=ar  hero search, featured listings, agents
function handle(req) {
  const p = page(req, {});
  const w = publicWhere(p.a);
  let rows = db.query('SELECT * FROM listings WHERE ' + w + ' AND featured = 1 ORDER BY coalesce(published, created_at) DESC, id DESC LIMIT 6');
  if (rows.length === 0) rows = db.query('SELECT * FROM listings WHERE ' + w + ' ORDER BY coalesce(published, created_at) DESC, id DESC LIMIT 6');
  p.featured = rows.map(l => card(l, p.lang, p.t));
  p.agents = db.query('SELECT * FROM agents WHERE active = 1 ORDER BY id LIMIT 12').map(x => agentCard(x, p.lang));
  p.form = searchForm(p.a, p.t, {purpose: '', type: '', community: '', beds: -1, min: 0, max: 0});
  p.about = pick(p.a, 'about', p.lang);
  return {template: 'home', data: p};
}

