  c.developer = l.offplan ? l.developer : '';
  c.handover = l.offplan ? l.handover : '';
  c.emirate = l.emirate;
  const agent = l.agent_id ? db.query('SELECT * FROM agents WHERE id = ? AND active = 1', l.agent_id)[0] : null;
  p.listing = c;
  p.agent = agent ? agentCard(agent, p.lang) : null;
  // The visitor taps this link; WhatsApp opens with the reference already typed.
  p.contactWa = p.agent && p.agent.wa ? p.agent.wa : p.wa;
  p.contactPhone = p.agent && p.agent.phone ? p.agent.phone : p.a.phone;
