// Job: every morning, email (and WhatsApp, if turned on) the owner what needs attention.
// It runs once a day, so "new" means the last 24 hours.
function handle(req) {
  const since = utc(-24 * 3600 * 1000);
  const kinds = db.query("SELECT kind, COUNT(*) AS n FROM leads WHERE created_at >= ? AND status != 'spam' GROUP BY kind ORDER BY kind", since);
  let fresh = 0;
  for (const k of kinds) fresh += k.n;
  const waiting = db.query("SELECT id, kind, name, phone FROM leads WHERE status = 'new' AND created_at < ? ORDER BY id LIMIT 20", since);
  const waitingAll = db.query("SELECT COUNT(*) AS n FROM leads WHERE status = 'new' AND created_at < ?", since)[0].n;
  const noPermit = db.query("SELECT reference, title FROM listings WHERE status IN ('available', 'reserved') AND trim(coalesce(permit_number, '')) = '' ORDER BY id LIMIT 20");
  const stale = db.query("SELECT reference, title FROM listings WHERE status = 'available' AND coalesce(published, created_at) < ? ORDER BY id LIMIT 20", utc(-60 * 24 * 3600 * 1000));
  if (fresh === 0 && waitingAll === 0 && noPermit.length === 0 && stale.length === 0) return {text: 'nothing to report'};
  const hidden = agency().hide_without_permit !== 0;
  const s = (n, one, many) => n + ' ' + (n === 1 ? one : many);
  const summary = s(fresh, 'new lead', 'new leads') + ' in the last 24 hours, ' + waitingAll + ' waiting over 24 hours, ' + s(noPermit.length, 'listing', 'listings') + ' without a permit number';
  let text = 'New leads in the last 24 hours: ' + fresh + '\n' + kinds.map(k => '  ' + k.kind + ': ' + k.n).join('\n');
  text += '\n\nLeads still "new" after 24 hours: ' + waitingAll + '\n' + waiting.map(l => '  #' + l.id + ' ' + l.kind + ', ' + l.name + ', ' + l.phone).join('\n');
  text += '\n\nListings without a permit number' + (hidden ? ' (not shown on the site)' : '') + ': ' + noPermit.length + '\n' + noPermit.map(l => '  ' + l.reference + ' ' + l.title).join('\n');
  text += '\n\nListings available for more than 60 days: ' + stale.length + '\n' + stale.map(l => '  ' + l.reference + ' ' + l.title).join('\n');
  try { notify.owner({subject: 'Leads: ' + summary, text: text}); } catch (e) { console.warn('owner not notified: ' + e); }
  return {text: summary + ', ' + s(stale.length, 'listing', 'listings') + ' older than 60 days'};
}
